import com.wmmt.port.DataOverlay;
import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.FileTime;
import java.security.MessageDigest;
import java.util.*;
import java.util.zip.*;

public final class DataOverlayHostTest {
  static byte[] bytes(String s) throws Exception {return s.getBytes("UTF-8");}
  static String hash(byte[] b)throws Exception{byte[] h=MessageDigest.getInstance("SHA-256").digest(b);StringBuilder s=new StringBuilder();for(byte x:h)s.append(String.format("%02x",x&255));return s.toString();}
  static DataOverlay.Entry ent(String s)throws Exception{byte[] b=bytes(s);return new DataOverlay.Entry(b.length,hash(b));}
  static byte[] zip(Map<String,String> entries)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(b)){for(Map.Entry<String,String> e:entries.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(bytes(e.getValue()));z.closeEntry();}}return b.toByteArray();}
  static void ok(boolean b,String m){if(!b)throw new AssertionError(m);}
  interface Op {void run()throws Exception;}
  static void fails(Op op)throws Exception{try{op.run();throw new AssertionError("expected IOException");}catch(IOException good){}}
  static class Fixture {
    Path base,root,state;Map<String,DataOverlay.Entry> old=new TreeMap<>(),next=new TreeMap<>();byte[] zip;String zh,oh;
    Fixture()throws Exception{
      base=Files.createTempDirectory("overlay-test-").toRealPath();root=Files.createDirectory(base.resolve("root"));state=Files.createDirectory(base.resolve("state"));
      Files.write(root.resolve("changed"),bytes("old"));Files.write(root.resolve("same"),bytes("same"));Files.write(root.resolve("removed"),bytes("keep removed"));Files.write(root.resolve("extra"),bytes("keep extra"));
      Files.createDirectory(root.resolve("obsolete"));Files.write(root.resolve("obsolete/old"),bytes("obsolete"));Files.write(root.resolve("modified"),bytes("user edit"));Files.createDirectory(root.resolve("was-file"));Files.createSymbolicLink(root.resolve("old-link"),root.resolve("extra"));
      old.put("changed",ent("old"));old.put("same",ent("same"));old.put("removed",ent("keep removed"));old.put("obsolete/old",ent("obsolete"));old.put("modified",ent("original"));old.put("was-file",ent("file"));old.put("old-link",ent("keep extra"));next.put("changed",ent("new"));next.put("same",ent("same"));next.put("sub/new",ent("added"));
      Map<String,String> z=new LinkedHashMap<>();z.put("changed","new");z.put("same","same");z.put("sub/new","added");z.put("../escape","bad");zip=zip(z);zh=hash(zip);oh=hash(bytes("old zip"));
    }
    DataOverlay.Source source(){return ()->new ByteArrayInputStream(zip);}
    void apply(DataOverlay.Fault f)throws Exception{DataOverlay.apply(root,state,old,next,source(),oh,zh,f);}
    void confirm()throws Exception{DataOverlay.confirm(root,state,old,next,oh,zh);}
    void verify()throws Exception{ok(Arrays.equals(Files.readAllBytes(root.resolve("changed")),bytes("new")),"changed");ok(Arrays.equals(Files.readAllBytes(root.resolve("sub/new")),bytes("added")),"added");ok(Files.exists(root.resolve("extra"))&&!Files.exists(root.resolve("removed"))&&!Files.exists(root.resolve("obsolete/old")),"remove unchanged old-only; keep extra");ok(Files.isDirectory(root.resolve("obsolete"))&&Files.isDirectory(root.resolve("was-file"))&&Files.isSymbolicLink(root.resolve("old-link"))&&Arrays.equals(Files.readAllBytes(root.resolve("modified")),bytes("user edit")),"keep changed and non-regular");ok(!Files.exists(base.resolve("escape")),"zip traversal");}
  }
  public static void main(String[] args)throws Exception{
    Fixture a=new Fixture();FileTime t=FileTime.fromMillis(1500000000000L);Files.setLastModifiedTime(a.root.resolve("same"),t);a.apply(null);a.verify();ok(Files.getLastModifiedTime(a.root.resolve("same")).equals(t),"unchanged mtime");a.apply(null);a.confirm();
    DataOverlay.apply(a.root,a.state,a.next,a.next,a.source(),a.zh,a.zh,null);DataOverlay.confirm(a.root,a.state,a.next,a.next,a.zh,a.zh);DataOverlay.confirm(a.root,a.state,a.next,a.next,a.zh,a.zh);
    Fixture committed=new Fixture();committed.apply(null);FileTime done=Files.getLastModifiedTime(committed.root.resolve("changed"));Path manifestTemp=committed.state.resolve("caller-manifest.tmp");Files.write(manifestTemp,bytes("new manifest committed"));Files.move(manifestTemp,committed.state.resolve("caller-manifest"),StandardCopyOption.ATOMIC_MOVE); // crash before confirm: caller retained old inputs
    committed.apply(null);committed.verify();ok(Files.getLastModifiedTime(committed.root.resolve("changed")).equals(done),"commit/restart does not overwrite");committed.confirm();committed.confirm();ok(Files.exists(committed.state.resolve("caller-manifest")),"caller manifest preserved");
    List<String> stages=Arrays.asList("before-zip-hash","after-zip-hash","before-journal-write","after-journal-write","after-journal-rename","after-journal-sync","before-mkdir","after-mkdir","before-temp-write","during-temp-write","after-temp-write","after-temp-sync","before-replace","after-replace","after-replace-sync","after-verify","before-old-delete","after-old-delete","after-old-delete-sync");
    for(String stage:stages){Fixture probe=new Fixture();int[] count={0};probe.apply((s,p)->{if(s.equals(stage))count[0]++;});ok(count[0]>0,"hook "+stage);for(int index=0;index<count[0];index++){final int stop=index;Fixture f=new Fixture();int[] seen={0};boolean[] fired={false};fails(()->f.apply((s,p)->{if(s.equals(stage)&&seen[0]++==stop){fired[0]=true;throw new IOException("crash");}}));ok(fired[0],"hook "+stage);f.apply(null);f.verify();f.confirm();}}
    Fixture journalSync=new Fixture();fails(()->journalSync.apply((s,p)->{if(s.equals("directory-sync")&&p.equals(journalSync.state.toString()))throw new IOException("sync unavailable");}));ok(Arrays.equals(Files.readAllBytes(journalSync.root.resolve("changed")),bytes("old")),"no overwrite without durable journal directory");journalSync.apply(null);journalSync.verify();journalSync.confirm();
    Fixture retrySync=new Fixture();fails(()->retrySync.apply((s,p)->{if(s.equals("after-replace")&&p.equals("sub/new"))throw new IOException("crash before parent sync");}));Set<String> syncedPaths=new HashSet<>();DataOverlay.Result syncedResult=DataOverlay.apply(retrySync.root,retrySync.state,retrySync.old,retrySync.next,retrySync.source(),retrySync.oh,retrySync.zh,(s,p)->{if(s.equals("directory-sync"))syncedPaths.add(p);});ok(syncedResult.directoriesSynced,"recovery sync success");ok(syncedPaths.contains(retrySync.root.toString())&&syncedPaths.contains(retrySync.root.resolve("sub").toString())&&syncedPaths.contains(retrySync.state.toString()),"recovery syncs all affected dirs");retrySync.confirm();
    Fixture targetSync=new Fixture();DataOverlay.Result failedSync=DataOverlay.apply(targetSync.root,targetSync.state,targetSync.old,targetSync.next,targetSync.source(),targetSync.oh,targetSync.zh,(s,p)->{if(s.equals("directory-sync")&&p.equals(targetSync.root.toString()))throw new IOException("target sync unavailable");});ok(!failedSync.directoriesSynced,"target sync failure reported");ok(Files.exists(targetSync.state.resolve("overlay.journal")),"journal retained on sync failure");targetSync.apply(null);targetSync.confirm();DataOverlay.Result confirmNoJournal=DataOverlay.confirm(targetSync.root,targetSync.state,targetSync.old,targetSync.next,targetSync.oh,targetSync.zh,(s,p)->{if(s.equals("directory-sync")&&p.equals(targetSync.state.toString()))throw new IOException("state sync unavailable");});ok(!confirmNoJournal.directoriesSynced,"confirm without journal sync failure reported");
    Fixture oldSync=new Fixture();boolean[] deleted={false};DataOverlay.Result oldSyncResult=DataOverlay.apply(oldSync.root,oldSync.state,oldSync.old,oldSync.next,oldSync.source(),oldSync.oh,oldSync.zh,(s,p)->{if(s.equals("after-old-delete")&&p.equals("obsolete/old"))deleted[0]=true;if(deleted[0]&&s.equals("directory-sync")&&p.equals(oldSync.root.resolve("obsolete").toString()))throw new IOException("delete sync unavailable");});ok(!oldSyncResult.directoriesSynced&&Files.exists(oldSync.state.resolve("overlay.journal")),"delete sync failure retains journal");Set<String> retriedDirs=new HashSet<>();DataOverlay.Result recoveredOld=DataOverlay.apply(oldSync.root,oldSync.state,oldSync.old,oldSync.next,oldSync.source(),oldSync.oh,oldSync.zh,(s,p)->{if(s.equals("directory-sync"))retriedDirs.add(p);});ok(recoveredOld.directoriesSynced&&retriedDirs.contains(oldSync.root.resolve("obsolete").toString()),"restart syncs deleted old parent");oldSync.verify();oldSync.confirm();
    for(boolean security:new boolean[]{false,true}){Fixture denied=new Fixture();DataOverlay.Result result=DataOverlay.apply(denied.root,denied.state,denied.old,denied.next,denied.source(),denied.oh,denied.zh,(s,p)->{if(s.equals("before-old-delete")&&p.equals("removed")){if(security)throw new SecurityException("denied");throw new AccessDeniedException(p);}});ok(result.directoriesSynced,"permission denial does not block upgrade");ok(Files.exists(denied.root.resolve("removed"))&&!Files.exists(denied.root.resolve("obsolete/old")),"denied old retained; other old removed");ok(Arrays.equals(Files.readAllBytes(denied.root.resolve("changed")),bytes("new")),"new version intact");denied.confirm();}
    Fixture deleteError=new Fixture();fails(()->deleteError.apply((s,p)->{if(s.equals("before-old-delete")&&p.equals("removed"))throw new IOException("disk error");}));ok(Files.exists(deleteError.state.resolve("overlay.journal"))&&Files.exists(deleteError.root.resolve("removed")),"unexpected delete failure retains journal and file");deleteError.apply(null);deleteError.verify();deleteError.confirm();
    Fixture oldParent=new Fixture();Files.createSymbolicLink(oldParent.root.resolve("old-parent"),oldParent.base);oldParent.old.put("old-parent/outside",ent("outside"));Files.write(oldParent.base.resolve("outside"),bytes("outside"));oldParent.apply(null);ok(Files.exists(oldParent.base.resolve("outside")),"never traverse old symlink parent");oldParent.confirm();
    Fixture partial=new Fixture();fails(()->partial.apply((s,p)->{if(s.equals("after-replace"))throw new IOException("interrupted");}));ok(Files.exists(partial.root.resolve("removed")),"old-only survives incomplete new install");partial.apply(null);partial.verify();partial.confirm();
    Fixture corrupt=new Fixture();Files.write(corrupt.root.resolve("changed"),bytes("mod"));fails(()->corrupt.apply(null));ok(Arrays.equals(Files.readAllBytes(corrupt.root.resolve("changed")),bytes("mod")),"mod preserved");
    Fixture missing=new Fixture();Files.delete(missing.root.resolve("changed"));fails(()->missing.apply(null));
    Fixture occupied=new Fixture();Files.createDirectory(occupied.root.resolve("sub"));Files.write(occupied.root.resolve("sub/new"),bytes("added"));fails(()->occupied.apply(null));
    Fixture traversal=new Fixture();traversal.next.put("../escape",ent("bad"));fails(()->traversal.apply(null));
    Fixture mods=new Fixture();mods.next.put("mods/car",ent("bad"));fails(()->mods.apply(null));
    Fixture link=new Fixture();Files.delete(link.root.resolve("changed"));Files.createSymbolicLink(link.root.resolve("changed"),link.root.resolve("same"));fails(()->link.apply(null));
    Fixture parentLink=new Fixture();Files.createSymbolicLink(parentLink.root.resolve("sub"),parentLink.base);fails(()->parentLink.apply(null));
    Fixture mismatch=new Fixture();fails(()->DataOverlay.apply(mismatch.root,mismatch.state,mismatch.old,mismatch.next,mismatch.source(),mismatch.oh,hash(bytes("wrong")),null));
    Fixture changedTxn=new Fixture();fails(()->changedTxn.apply((s,p)->{if(s.equals("after-replace"))throw new IOException("stop");}));Map<String,DataOverlay.Entry> different=new TreeMap<>(changedTxn.next);different.put("other",ent("other"));fails(()->DataOverlay.apply(changedTxn.root,changedTxn.state,changedTxn.old,different,changedTxn.source(),changedTxn.oh,changedTxn.zh,null));changedTxn.apply(null);changedTxn.verify();changedTxn.confirm();
    Fixture newProtect=new Fixture();fails(()->newProtect.apply((s,p)->{if(s.equals("after-replace")&&p.equals("sub/new"))throw new IOException("stop");}));Files.write(newProtect.root.resolve("sub/new"),bytes("edit"));fails(()->newProtect.apply(null));ok(Arrays.equals(Files.readAllBytes(newProtect.root.resolve("sub/new")),bytes("edit")),"new modification preserved");
    Fixture failConfirm=new Fixture();fails(()->failConfirm.apply((s,p)->{if(s.equals("after-replace"))throw new IOException("stop");}));fails(()->failConfirm.confirm());Files.write(failConfirm.root.resolve("changed"),bytes("outside"));fails(()->failConfirm.apply(null));
    System.out.println("DataOverlay host tests passed: "+stages.size()+" injected restart stages");
  }
}
